function esc(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function id(){return crypto.randomUUID?crypto.randomUUID():`gt-${Date.now()}-${Math.random().toString(36).slice(2)}`}
function fmtDate(value){if(!value)return '—';const d=new Date(`${value}T00:00:00`);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('pt-BR')}
function fmtMoney(value){const n=Number(String(value||'').replace(',','.'));return n? n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'—'}
function norm(value){return String(value||'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function companyById(value){return data.companies.find(c=>c.id===value)}
function employeeById(value){return data.employees.find(c=>c.id===value)}
function companyName(value){return companyById(value)?.name||'—'}
function employeeName(value){return employeeById(value)?.name||''}
function daysUntil(value){if(!value)return null;const now=new Date();now.setHours(0,0,0,0);const due=new Date(`${value}T00:00:00`);return Math.ceil((due-now)/86400000)}
function docStatus(doc){const days=daysUntil(doc.expiryDate);if(days!==null&&days<0)return 'Vencido';if(doc.status==='Aprovado'&&days!==null&&days<=30)return 'Vence em breve';return doc.status||'Para análise'}
function statusClass(status){const s=norm(status);if(['aprovado','ativa','ativo','regular','vigente'].some(x=>s.includes(x)))return 'status-approved';if(['analise','pendente','revisao','breve','vence'].some(x=>s.includes(x)))return 'status-pending';if(['reprovado','vencido','irregular','atrasado'].some(x=>s.includes(x)))return 'status-rejected';if(['encerrado','inativo','concluido'].some(x=>s.includes(x)))return 'status-inactive';return 'status-inactive'}
function pill(status){return `<span class="status-pill ${statusClass(status)}">${esc(status)}</span>`}
function monogram(name){const words=String(name||'').trim().split(/\s+/).filter(Boolean);return esc((words[0]?.[0]||'E')+(words[1]?.[0]||'' )).toUpperCase()}
function initialsColor(index){return ['','teal','gold','purple'][index%4]}
function companyCell(company,index=0){return `<div class="company-cell"><span class="company-monogram ${initialsColor(index)}">${monogram(company?.name||'')}</span><span><span class="primary-cell">${esc(company?.name||'Empresa não localizada')}</span><span class="secondary-cell">${esc(company?.city||company?.cnpj||'')}</span></span></div>`}
function showToast(message,type=''){const region=document.getElementById('toast-region');const box=document.createElement('div');box.className=`toast ${type}`;box.innerHTML=`<span class="toast-icon">${type==='error'?'!':type==='success'?'✓':'•'}</span><span>${esc(message)}</span>`;region.appendChild(box);setTimeout(()=>box.remove(),4300)}
function titleBlock(title,description,actions=''){return `<div class="page-heading"><div><div class="page-kicker">CONTROLE DOCUMENTAL E CONTRATUAL</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
function searchMatch(...values){return !searchTerm||values.some(v=>norm(v).includes(norm(searchTerm)))}
function countCurrent(items){return items.length}
function emptyState(title,copy,iconName='file'){return `<div class="empty-state"><div class="empty-state-icon">${icon(iconName)}</div><strong>${title}</strong><span>${copy}</span></div>`}
function syncWarning(){return `<div class="sync-warning ${syncState==='error'?'visible':''}" id="sync-warning"><span>Há alterações que ainda não foram sincronizadas com o Drive.</span><button data-action="sync">Tentar novamente</button></div>`}
function renderDashboard(){
  const docs=data.documents||[],employees=data.employees||[],companies=data.companies||[],contracts=data.contracts||[];
  const overdue=docs.filter(d=>docStatus(d)==='Vencido'),soon=docs.filter(d=>docStatus(d)==='Vence em breve'),pending=docs.filter(d=>!['Aprovado','Vence em breve'].includes(d.status));
  const needsAttention=[...new Map([...overdue,...soon,...pending].map(d=>[d.id,d])).values()];
  const expiring=needsAttention.sort((a,b)=>(daysUntil(a.expiryDate)??999)-(daysUntil(b.expiryDate)??999)).slice(0,5);
  const dueContracts=contracts.filter(c=>c.status==='Ativo'&&daysUntil(c.endDate)!==null&&daysUntil(c.endDate)<=60).sort((a,b)=>daysUntil(a.endDate)-daysUntil(b.endDate)).slice(0,4);
  const valid=docs.filter(d=>['Aprovado','Vence em breve'].includes(docStatus(d))).length;
  const compliance=docs.length?Math.round(valid/docs.length*100):0;
  const dueRows=expiring.map(d=>`<tr><td><div class="doc-name"><span class="file-type-icon">${icon('file')}</span><span><span class="primary-cell">${esc(d.type)}</span><span class="secondary-cell">${esc(d.fileName||'')}</span></span></div></td><td>${companyCell(companyById(d.companyId),1)}</td><td>${fmtDate(d.expiryDate)}</td><td>${pill(docStatus(d))}</td><td>${d.driveUrl?`<a class="subtle-action doc-link" href="${esc(d.driveUrl)}" target="_blank" rel="noopener">Abrir</a>`:'<span class="muted">Exemplo</span>'}</td></tr>`).join('');
  const contractRows=dueContracts.map(c=>`<div class="mini-row"><span class="mini-row-icon">${icon('contract')}</span><span class="mini-row-copy"><strong>${esc(companyName(c.companyId))}</strong><span>${esc(c.number||'Contrato')} · termina ${fmtDate(c.endDate)}</span></span><span class="mini-row-tail">${daysUntil(c.endDate)} dias</span></div>`).join('');
  const companyRows=companies.slice(0,4).map((c,i)=>{const companyDocs=docs.filter(d=>d.companyId===c.id);const companyValid=companyDocs.filter(d=>['Aprovado','Vence em breve'].includes(docStatus(d))).length;const pct=companyDocs.length?Math.round(companyValid/companyDocs.length*100):0;return `<div class="company-compliance-row"><span class="primary-cell">${esc(c.name)}</span><span>${companyDocs.length} docs.</span><div class="progress-track"><span style="width:${pct}%"></span></div><span>${pct}%</span></div>`}).join('');
  const activity=docs.slice(0,4).map(d=>`<div class="activity-item"><span class="activity-icon">${icon(docStatus(d)==='Vencido'?'alert':'file')}</span><div><p><strong>${esc(d.type)}</strong> · ${esc(companyName(d.companyId))}</p><time>${d.issueDate?`Referência ${fmtDate(d.issueDate)}`:'Documento cadastrado'}</time></div></div>`).join('');
  return `${!driveConnected?`<div class="demo-banner"><span class="demo-banner-icon">${icon('shield')}</span><div class="demo-banner-copy"><strong>Visualização demonstrativa</strong><span>Os números e nomes abaixo são exemplos. Conecte o Drive e vincule as pastas das empresas para importar os arquivos.</span></div><button class="button button-primary" data-action="open-settings">Configurar Drive ${icon('arrow-right')}</button></div>`:''}
  ${syncWarning()}
  <div class="metric-grid">
   <article class="metric-card"><div class="metric-top"><span class="metric-label">Empresas cadastradas</span><span class="metric-icon">${icon('building')}</span></div><div class="metric-value">${companies.length}</div><div class="metric-foot"><span class="trend-up">${companies.filter(c=>c.status==='Ativa').length} ativas</span><span>no monitoramento</span></div></article>
   <article class="metric-card"><div class="metric-top"><span class="metric-label">Colaboradores</span><span class="metric-icon teal">${icon('users')}</span></div><div class="metric-value">${employees.length}</div><div class="metric-foot"><span>${employees.filter(e=>e.status==='Ativo').length} ativos</span><span>vinculados às empresas</span></div></article>
   <article class="metric-card"><div class="metric-top"><span class="metric-label">Documentos para atenção</span><span class="metric-icon amber">${icon('alert')}</span></div><div class="metric-value">${overdue.length+soon.length+pending.length}</div><div class="metric-foot"><span class="trend-down">${overdue.length} vencidos</span><span>· ${pending.length} em análise</span></div></article>
   <article class="metric-card"><div class="metric-top"><span class="metric-label">Contratos ativos</span><span class="metric-icon red">${icon('contract')}</span></div><div class="metric-value">${contracts.filter(c=>c.status==='Ativo').length}</div><div class="metric-foot"><span>${dueContracts.length} terminam em até 60 dias</span></div></article>
  </div>
  <div class="dashboard-grid">
   <section class="panel"><div class="panel-header"><div><h2>Documentos que precisam de atenção</h2><p>Vencimentos e análises pendentes das empresas monitoradas</p></div><button class="text-link" data-page-link="documents">Ver todos ${icon('arrow-right')}</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Documento</th><th>Empresa</th><th>Vencimento</th><th>Situação</th><th></th></tr></thead><tbody>${dueRows||`<tr><td colspan="5">${emptyState(docs.length?'Tudo em dia':'Nenhum documento cadastrado','Envie documentos para começar o acompanhamento.','file')}</td></tr>`}</tbody></table></div></section>
   <div class="dashboard-side">
    <section class="panel compliance-panel"><div class="panel-header"><div><h2>Regularidade documental</h2><p>Visão consolidada das empresas</p></div><span class="metric-icon teal">${icon('shield')}</span></div><div class="compliance-main"><div class="donut" style="--progress:${compliance}%"><div class="donut-center"><strong>${compliance}%</strong><span>regular</span></div></div><div class="compliance-text"><strong>${valid} de ${docs.length} documentos</strong><span>aprovados e dentro do prazo de validade</span></div></div><div class="legend-list"><div class="legend-row"><i class="legend-dot"></i>Regular <strong>${valid}</strong></div><div class="legend-row"><i class="legend-dot amber"></i>Em análise <strong>${pending.length}</strong></div><div class="legend-row"><i class="legend-dot red"></i>Vencido ou próximo do vencimento <strong>${overdue.length+soon.length}</strong></div></div></section>
    <section class="panel activity-panel"><div class="panel-header"><div><h2>Movimentações recentes</h2><p>Últimos documentos registrados</p></div><span class="metric-icon">${icon('activity')}</span></div><div class="activity-list">${activity||emptyState('Sem movimentações','Os documentos enviados aparecerão aqui.','activity')}</div></section>
   </div>
  </div>
  <div class="secondary-grid">
   <section class="panel"><div class="panel-header"><div><h2>Regularidade por empresa</h2><p>Proporção de documentos aprovados e vigentes</p></div><button class="text-link" data-page-link="companies">Empresas ${icon('arrow-right')}</button></div><div class="company-compliance-list">${companyRows||emptyState('Sem empresas','Vincule uma pasta de empresa para iniciar.','building')}</div></section>
   <section class="panel"><div class="panel-header"><div><h2>Contratos próximos do término</h2><p>Contratos com encerramento em até 60 dias</p></div><button class="text-link" data-page-link="contracts">Contratos ${icon('arrow-right')}</button></div><div class="mini-list">${contractRows||emptyState('Sem vencimentos próximos','Os contratos cadastrados aparecerão aqui.','contract')}</div></section>
  </div>`;
}
function renderCompanies(){const items=data.companies.filter(c=>searchMatch(c.name,c.cnpj,c.contact,c.city));const rows=items.map((c,i)=>{const staff=data.employees.filter(e=>e.companyId===c.id).length;const docs=data.documents.filter(d=>d.companyId===c.id);const issues=docs.filter(d=>!['Aprovado','Vence em breve'].includes(d.status)||['Vencido'].includes(docStatus(d))).length;return `<tr><td>${companyCell(c,i)}</td><td>${esc(c.cnpj||'—')}</td><td>${esc(c.contact||'—')}<span class="secondary-cell">${esc(c.email||'')}</span></td><td>${staff}</td><td>${docs.length?pill(issues?`${issues} pendência${issues>1?'s':''}`:'Regular'):'<span class="muted">Sem documentos</span>'}</td><td>${pill(c.status||'Ativa')}</td><td class="actions-cell"><button class="subtle-action" data-edit="company" data-id="${esc(c.id)}">Editar</button></td></tr>`}).join('');
return `${titleBlock('Empresas','Cadastre as prestadoras e acompanhe a situação documental de cada uma.','<button class="button button-primary" data-action="add-company">'+icon('plus')+' Nova empresa</button>')}${syncWarning()}<div class="section-toolbar"><div class="toolbar-left"><span class="muted" style="font-size:9px">${items.length} empresa${items.length===1?'':'s'} localizada${items.length===1?'':'s'}</span></div><div class="toolbar-right"><button class="button button-small" data-action="open-settings">${icon('cloud')} Armazenamento</button></div></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table record-table"><thead><tr><th>Empresa</th><th>CNPJ</th><th>Contato responsável</th><th>Equipe</th><th>Documentação</th><th>Situação</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="7">${emptyState(searchTerm?'Nenhuma empresa encontrada':'Nenhuma empresa cadastrada',searchTerm?'Tente outro termo de busca.':'Adicione uma empresa para começar.','building')}</td></tr>`}</tbody></table></div><div class="table-footer">Os anexos e registros da plataforma ficam organizados na pasta conectada do Google Drive.</div></section>`}
function renderEmployees(){const items=data.employees.filter(e=>searchMatch(e.name,e.cpf,e.position,companyName(e.companyId)));const rows=items.map(e=>`<tr><td><div class="company-cell"><span class="company-monogram teal">${monogram(e.name)}</span><span><span class="primary-cell">${esc(e.name)}</span><span class="secondary-cell">CPF ${esc(e.cpf||'—')}</span></span></div></td><td>${esc(e.position||'—')}</td><td>${companyCell(companyById(e.companyId),1)}</td><td>${fmtDate(e.admissionDate)}</td><td>${pill(e.status||'Ativo')}</td><td class="actions-cell"><button class="subtle-action" data-edit="employee" data-id="${esc(e.id)}">Editar</button></td></tr>`).join('');return `${titleBlock('Colaboradores','Mantenha o vínculo de cada trabalhador com a empresa prestadora e controle seus documentos.','<button class="button button-primary" data-action="add-employee">'+icon('plus')+' Novo colaborador</button>')}${syncWarning()}<div class="section-toolbar"><div class="toolbar-left"><span class="muted" style="font-size:9px">${items.length} colaborador${items.length===1?'':'es'}</span></div><div class="toolbar-right"><button class="button button-small" data-page-link="documents">${icon('file')} Ver documentos</button></div></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table record-table"><thead><tr><th>Colaborador</th><th>Cargo ou função</th><th>Empresa prestadora</th><th>Admissão</th><th>Situação</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="6">${emptyState(searchTerm?'Nenhum colaborador encontrado':'Nenhum colaborador cadastrado',searchTerm?'Tente outro termo de busca.':'Vincule as pastas das empresas primeiro e depois adicione colaboradores.','users')}</td></tr>`}</tbody></table></div></section>`}
function renderDocuments(){const items=data.documents.filter(d=>searchMatch(d.type,d.competency,d.fileName,companyName(d.companyId),employeeName(d.employeeId)));const rows=items.map(d=>`<tr><td><div class="doc-name"><span class="file-type-icon">${icon('file')}</span><span><span class="primary-cell">${esc(d.type)}</span><span class="secondary-cell">${esc(d.competency||d.fileName||'')}</span></span></div></td><td>${companyCell(companyById(d.companyId),1)}</td><td>${esc(employeeName(d.employeeId)||'Empresa')}</td><td>${fmtDate(d.issueDate)}</td><td>${fmtDate(d.expiryDate)}</td><td><select class="status-select ${statusClass(d.status)}" data-doc-status="${esc(d.id)}" aria-label="Alterar situação do documento"><option ${d.status==='Para análise'?'selected':''}>Para análise</option><option ${d.status==='Aprovado'?'selected':''}>Aprovado</option><option ${d.status==='Reprovado'?'selected':''}>Reprovado</option></select>${docStatus(d)==='Vencido'?'<span class="status-banner-inline">Vencido</span>':''}</td><td class="actions-cell">${d.driveUrl?`<a class="subtle-action doc-link" href="${esc(d.driveUrl)}" target="_blank" rel="noopener">Abrir arquivo</a>`:'<span class="muted">Exemplo</span>'}</td></tr>`).join('');return `${titleBlock('Documentos','Receba, organize e monitore a validade dos documentos das empresas e dos colaboradores.','<button class="button button-primary" data-action="add-document">'+icon('upload')+' Enviar documento</button>')}${syncWarning()}<div class="section-toolbar"><div class="toolbar-left"><select class="filter-select" id="doc-filter"><option value="all">Todas as situações</option><option value="attention">Com pendência ou vencimento</option><option value="approved">Aprovados</option></select><span class="muted" style="font-size:9px">${items.length} documento${items.length===1?'':'s'}</span></div><div class="toolbar-right"><button class="button button-small" data-action="open-settings">${icon('folder')} Pasta no Drive</button></div></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table record-table"><thead><tr><th>Documento</th><th>Empresa</th><th>Vinculado a</th><th>Emissão</th><th>Validade</th><th>Situação</th><th></th></tr></thead><tbody id="document-rows">${rows||`<tr><td colspan="7">${emptyState(searchTerm?'Nenhum documento encontrado':'Nenhum documento cadastrado','Use “Enviar documento” para anexar um arquivo diretamente no Google Drive.','file')}</td></tr>`}</tbody></table></div><div class="table-footer">Tipos sugeridos: certidões, folha e encargos, PGR, PCMSO, LTCAT, laudos de insalubridade/periculosidade, ASO, PPP e treinamentos.</div></section>`}
function renderContracts(){const items=data.contracts.filter(c=>searchMatch(c.number,companyName(c.companyId),c.status));const rows=items.map(c=>{const startRemain=daysUntil(c.startDate),remain=daysUntil(c.endDate);const total=Math.max(1,startRemain<0?Math.abs(startRemain)+(remain||0):(remain||0)-startRemain);const elapsed=startRemain<0?Math.abs(startRemain):0;const progress=Math.max(0,Math.min(100,Math.round(elapsed/total*100)));return `<tr><td><span class="primary-cell">${esc(c.number||'Contrato')}</span><span class="secondary-cell">${fmtMoney(c.monthlyValue)} / mês</span></td><td>${companyCell(companyById(c.companyId),1)}</td><td>${fmtDate(c.startDate)}</td><td>${fmtDate(c.endDate)}${remain!==null&&remain>=0&&remain<=60?`<span class="secondary-cell">Encerra em ${remain} dias</span>`:''}</td><td><span class="contract-progress"><span style="width:${progress}%"></span></span><span class="muted">${progress}%</span></td><td>${pill(c.status||'Ativo')}</td><td class="actions-cell"><button class="subtle-action" data-edit="contract" data-id="${esc(c.id)}">Editar</button></td></tr>`}).join('');return `${titleBlock('Contratos','Controle vigência, prestadora vinculada e principais informações de cada contrato.','<button class="button button-primary" data-action="add-contract">'+icon('plus')+' Novo contrato</button>')}${syncWarning()}<div class="section-toolbar"><div class="toolbar-left"><span class="muted" style="font-size:9px">${items.length} contrato${items.length===1?'':'s'}</span></div><div class="toolbar-right"><button class="button button-small" data-page-link="documents">${icon('file')} Anexar contrato</button></div></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table record-table"><thead><tr><th>Identificação</th><th>Empresa prestadora</th><th>Início</th><th>Término</th><th>Vigência</th><th>Situação</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="7">${emptyState(searchTerm?'Nenhum contrato encontrado':'Nenhum contrato cadastrado','Adicione os contratos para acompanhar seus prazos.','contract')}</td></tr>`}</tbody></table></div></section>`}
function renderReports(){const docs=data.documents;const companies=data.companies;const approved=docs.filter(d=>['Aprovado','Vence em breve'].includes(docStatus(d))).length;const overdue=docs.filter(d=>docStatus(d)==='Vencido').length;const pending=docs.filter(d=>!['Aprovado','Vence em breve','Vencido'].includes(d.status)).length;const companyRows=companies.map(c=>{const cd=docs.filter(d=>d.companyId===c.id);const good=cd.filter(d=>['Aprovado','Vence em breve'].includes(docStatus(d))).length;const percent=cd.length?Math.round(good/cd.length*100):0;return `<div class="company-compliance-row"><span class="primary-cell">${esc(c.name)}</span><span>${cd.length} documentos</span><div class="progress-track"><span style="width:${percent}%"></span></div><span>${percent}%</span></div>`}).join('');return `${titleBlock('Relatórios','Acompanhe a regularidade documental e exporte uma relação para conferência.','<button class="button" data-action="export-csv">'+icon('download')+' Exportar CSV</button>')}${syncWarning()}<div class="report-grid"><article class="report-card"><span class="metric-icon teal">${icon('shield')}</span><h3>Resumo de regularidade</h3><p>Visão consolidada dos documentos aprovados, pendentes e vencidos.</p><strong>${approved} regulares</strong></article><article class="report-card"><span class="metric-icon amber">${icon('clock')}</span><h3>Pendências de análise</h3><p>Documentos enviados que ainda precisam de conferência e definição de situação.</p><strong>${pending} aguardando análise</strong></article><article class="report-card"><span class="metric-icon red">${icon('alert')}</span><h3>Documentos vencidos</h3><p>Itens cuja data de validade já passou e precisam ser atualizados.</p><strong>${overdue} vencidos</strong></article></div><section class="panel"><div class="panel-header"><div><h2>Regularidade por empresa</h2><p>Percentual de documentos aprovados e dentro da validade</p></div><span class="metric-icon">${icon('chart')}</span></div><div class="company-compliance-list">${companyRows||emptyState('Sem dados para exibir','Vincule pastas e sincronize documentos para gerar o relatório.','chart')}</div></section>`}
function renderSettings(){const clientId=localStorage.getItem(CLIENT_KEY)||'';const folderLink=driveFolderId?`https://drive.google.com/drive/folders/${encodeURIComponent(driveFolderId)}`:'';return `${titleBlock('Configurações','Conecte o Drive e defina onde a plataforma salvará os cadastros e anexos.','')}${syncWarning()}<div class="settings-grid"><section class="panel settings-panel"><h2>Armazenamento no Google Drive</h2><p class="settings-intro">A conexão é feita na sua conta Google. Os anexos enviados pelo portal e o arquivo de dados da plataforma ficam na pasta criada para este sistema.</p><div class="settings-status"><span class="settings-status-icon">${icon(driveConnected?'check':'cloud')}</span><div class="settings-status-copy"><strong>${driveConnected?'Drive conectado':'Drive ainda não conectado'}</strong><span>${driveConnected?'Os cadastros e os anexos estão sendo sincronizados com a pasta abaixo.':'Para ativar o envio, configure o identificador OAuth do Google e autorize o acesso.'}</span></div>${driveConnected?`<button class="button button-small" data-action="disconnect-drive">Desconectar</button>`:''}</div>${driveConnected?`<div class="field"><label>Pasta de armazenamento</label><a class="folder-line" href="${esc(folderLink)}" target="_blank" rel="noopener">${icon('folder')} Abrir pasta “BancoDoc” no Drive ${icon('arrow-up-right')}</a><small>Os arquivos anexados e o banco de dados JSON da plataforma são guardados nesta pasta privada.</small></div>`:''}<div class="field"><label for="google-client-id">ID do cliente OAuth do Google</label><input id="google-client-id" type="text" inputmode="url" autocomplete="off" spellcheck="false" placeholder="000000000000-abc123.apps.googleusercontent.com" value="${esc(clientId)}"><small>É o Client ID de um OAuth 2.0 do tipo “Aplicativo da Web”. Não coloque o Client Secret. O Client ID é público e fica salvo somente nas configurações deste navegador.</small></div><div class="form-actions"><button class="button" data-action="save-client-id">Salvar configuração</button><button class="button button-primary" data-action="connect-drive">${icon('cloud')} ${driveConnected?'Reconectar ao Google Drive':'Conectar Google Drive'}</button></div><div class="sync-warning ${syncState==='error'?'visible':''}" id="sync-warning"><span>Há alterações que ainda não foram sincronizadas com o Drive.</span><button data-action="sync">Tentar novamente</button></div></section><aside class="info-card"><h3>Como preparar a conexão</h3><p>O consentimento usa <strong>drive.file</strong> para gravar os dados do BancoDoc e <strong>drive.metadata.readonly</strong> para consultar metadados do Drive da conta. O BancoDoc lista apenas as pastas vinculadas e não baixa o conteúdo dos documentos.</p><ul><li>Crie um projeto no Google Cloud Console e habilite a Google Drive API.</li><li>Configure a tela de consentimento OAuth e adicione sua conta como usuária de teste.</li><li>Crie uma credencial OAuth 2.0 do tipo Aplicativo da Web.</li><li>Inclua esta origem autorizada: <span class="connection-code">https://gestao-de-terceiros.elizangelay2.chatgpt.site</span></li><li>Copie o Client ID nesta tela e clique em “Conectar Google Drive”.</li></ul><p>Na primeira conexão, será criada a pasta “BancoDoc” e o arquivo de cadastros. Os anexos serão enviados para essa pasta.</p><p class="privacy-note">A plataforma não armazena tokens de acesso no navegador. Os dados de cadastro ficam em um arquivo JSON no Drive conectado. O portal é privado e restrito à conta autorizada a acessar este site.</p></aside></div>`}
function renderPage(){const content=document.getElementById('page-content');const renderers={dashboard:renderDashboard,companies:renderCompanies,employees:renderEmployees,documents:renderDocuments,contracts:renderContracts,reports:renderReports,settings:renderSettings};content.innerHTML=(renderers[page]||renderDashboard)();document.querySelectorAll('.nav-item[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));document.getElementById('breadcrumb-current').textContent=({dashboard:'Visão geral',companies:'Empresas',employees:'Colaboradores',documents:'Documentos',contracts:'Contratos',reports:'Relatórios',settings:'Configurações'})[page]||'Visão geral';document.getElementById('company-count').textContent=data.companies.length;const attention=data.documents.filter(d=>docStatus(d)==='Vencido'||d.status==='Para análise').length;document.getElementById('document-alert-dot').style.display=attention?'block':'none';if(page==='documents'){const filter=document.getElementById('doc-filter');filter?.addEventListener('change',()=>{document.querySelectorAll('#document-rows tr').forEach(row=>{const text=row.innerText;const status=row.querySelector('.status-select')?.value||'';const computed=text.includes('Vencido');const show=filter.value==='all'||(filter.value==='approved'&&status==='Aprovado')||(filter.value==='attention'&&(status!=='Aprovado'||computed));row.style.display=show?'':'none'})})}if(page==='settings'){document.getElementById('google-client-id')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveClientId()}})}}
function updateDriveUi(){const label=document.getElementById('drive-status-label'),button=document.getElementById('drive-status'),sideTitle=document.getElementById('sidebar-drive-title'),sideCopy=document.getElementById('sidebar-drive-copy');if(driveConnected){label.textContent='Drive conectado';button.classList.add('connected');sideTitle.textContent='Drive conectado';sideCopy.textContent='Pastas das empresas vinculadas.'}else if(syncState==='connecting'){label.textContent='Conectando…';button.classList.remove('connected');sideTitle.textContent='Conectando ao Drive';sideCopy.textContent='Aguarde a autorização da sua conta.'}else{label.textContent='Drive desconectado';button.classList.remove('connected');sideTitle.textContent='Drive desconectado';sideCopy.textContent='Conecte sua conta e vincule pastas.'}}
function setPage(next){page=next;searchTerm='';document.getElementById('global-search').value='';renderPage();document.body.classList.remove('mobile-open');document.getElementById('mobile-backdrop').classList.remove('show');window.scrollTo({top:0,behavior:'smooth'})}

function companyOptions(selected=''){return `<option value="">Selecione uma empresa</option>${data.companies.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('')}`}
function employeeOptions(companyId='',selected=''){const list=data.employees.filter(e=>!companyId||e.companyId===companyId);return `<option value="">Empresa (sem colaborador específico)</option>${list.map(e=>`<option value="${esc(e.id)}" ${e.id===selected?'selected':''}>${esc(e.name)}</option>`).join('')}`}
function openModal(title,subtitle,body){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button></div>${body}</section></div>`;document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});document.querySelector('#record-form input:not([type=hidden]),#record-form select')?.focus()}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function field(label,name,value='',type='text',placeholder='',required=false){return `<div class="field"><label for="field-${name}">${label}${required?' *':''}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''}></div>`}
function renderCompanyForm(record){const c=record||{};openModal(c.id?'Editar empresa':'Cadastrar empresa','Dados básicos da prestadora e contato responsável.',`<form class="modal-form" id="record-form" data-kind="company"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="field-row">${field('Razão social ou nome da empresa','name',c.name||'', 'text','Nome cadastrado',true)}${field('CNPJ','cnpj',c.cnpj||'','text','00.000.000/0000-00')}</div><div class="field-row">${field('Responsável pelo contato','contact',c.contact||'','text','Nome da pessoa')}${field('Cidade/UF','city',c.city||'','text','Cataguases/MG')}</div><div class="field-row">${field('E-mail','email',c.email||'','email','contato@empresa.com')}${field('Telefone','phone',c.phone||'','tel','(00) 00000-0000')}</div><div class="field"><label for="field-company-status">Situação</label><select id="field-company-status" name="status"><option ${c.status!=='Inativa'?'selected':''}>Ativa</option><option ${c.status==='Inativa'?'selected':''}>Inativa</option></select></div><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">Salvar empresa</button></div></form>`)}
function renderEmployeeForm(record){const e=record||{};openModal(e.id?'Editar colaborador':'Cadastrar colaborador','Vincule o colaborador à empresa prestadora responsável.',`<form class="modal-form" id="record-form" data-kind="employee"><input type="hidden" name="id" value="${esc(e.id||'')}"><div class="field-row">${field('Nome completo','name',e.name||'','text','Nome do colaborador',true)}${field('CPF','cpf',e.cpf||'','text','000.000.000-00')}</div><div class="field-row"><div class="field"><label for="field-companyId">Empresa prestadora *</label><select id="field-companyId" name="companyId" required>${companyOptions(e.companyId||'')}</select></div>${field('Cargo ou função','position',e.position||'','text','Ex.: Auxiliar de serviços gerais')}</div><div class="field-row">${field('Data de admissão','admissionDate',e.admissionDate||'','date')}${field('Telefone','phone',e.phone||'','tel','(00) 00000-0000')}</div><div class="field"><label for="field-employee-status">Situação</label><select id="field-employee-status" name="status"><option ${e.status!=='Inativo'?'selected':''}>Ativo</option><option ${e.status==='Inativo'?'selected':''}>Inativo</option></select></div><p class="form-footnote">Evite inserir informações médicas no cadastro. Os documentos são armazenados diretamente no Drive.</p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">Salvar colaborador</button></div></form>`)}
function renderContractForm(record){const c=record||{};openModal(c.id?'Editar contrato':'Cadastrar contrato','Registre a vigência e a empresa vinculada.',`<form class="modal-form" id="record-form" data-kind="contract"><input type="hidden" name="id" value="${esc(c.id||'')}"><div class="field-row">${field('Número ou identificação','number',c.number||'','text','Ex.: CT-2026-001',true)}<div class="field"><label for="field-companyId">Empresa prestadora *</label><select id="field-companyId" name="companyId" required>${companyOptions(c.companyId||'')}</select></div></div><div class="field-row">${field('Início da vigência','startDate',c.startDate||'','date', '',true)}${field('Término da vigência','endDate',c.endDate||'','date','',true)}</div><div class="field-row">${field('Valor mensal (R$)','monthlyValue',c.monthlyValue||'','number','0,00')}<div class="field"><label for="field-contract-status">Situação</label><select id="field-contract-status" name="status"><option ${c.status!=='Encerrado'?'selected':''}>Ativo</option><option ${c.status==='Encerrado'?'selected':''}>Encerrado</option></select></div></div><div class="field"><label for="field-notes">Observações</label><textarea id="field-notes" name="notes" placeholder="Informações importantes sobre a vigência">${esc(c.notes||'')}</textarea></div><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">Salvar contrato</button></div></form>`)}
const DOC_TYPES=['Guia de INSS','Guia de FGTS','Guia de DCTFWeb/DARF','Comprovante de pagamento de guia','Certidão federal','Certidão estadual','Certidão municipal','Certidão de regularidade do FGTS','CNDT','Ficha de EPI','Comprovante de folha de pagamento','Comprovante de encargos/tributos','PGR','PCMSO','LTCAT','Laudo de insalubridade','Laudo de periculosidade','ASO admissional','ASO periódico','ASO demissional','PPP','CAT','Treinamento/NR','Documento de identificação','Outro'];
function renderDocumentForm(){openModal('Enviar documento','O arquivo será enviado diretamente para a pasta “BancoDoc” no seu Google Drive.',`<form class="modal-form" id="record-form" data-kind="document"><div class="form-section-label">Identificação</div><div class="field"><label for="field-file">Arquivo *</label><input id="field-file" name="file" type="file" required><small>PDF, imagem ou outro arquivo. Máximo recomendado: 50 MB.</small></div><div class="field-row"><div class="field"><label for="field-companyId">Empresa prestadora *</label><select id="field-companyId" name="companyId" required>${companyOptions()}</select></div><div class="field"><label for="field-type">Tipo de documento *</label><select id="field-type" name="type" required><option value="">Selecione</option>${DOC_TYPES.map(t=>`<option>${esc(t)}</option>`).join('')}</select></div></div><div class="field"><label for="field-employeeId">Colaborador (opcional)</label><select id="field-employeeId" name="employeeId">${employeeOptions()}</select></div><div class="field-row">${field('Competência ou período','competency','','text','Ex.: 09/2026')}${field('Data de emissão','issueDate','','date')}</div><div class="field-row">${field('Validade até','expiryDate','','date')}<div class="field"><label for="field-document-status">Situação inicial</label><select id="field-document-status" name="status"><option>Para análise</option><option>Aprovado</option></select></div></div><div class="field"><label for="field-document-notes">Observações (opcional)</label><textarea id="field-document-notes" name="notes" placeholder="Anotações de conferência, sem dados médicos detalhados"></textarea></div><p class="form-footnote">O arquivo sai do navegador e é enviado ao Drive autorizado. O portal guarda no Drive também os dados de controle (empresa, tipo, datas e situação).</p><div class="form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">${icon('upload')} Enviar para o Drive</button></div></form>`);document.getElementById('field-companyId')?.addEventListener('change',e=>{const emp=document.getElementById('field-employeeId');if(emp)emp.innerHTML=employeeOptions(e.target.value)})}
function openForm(kind,record){if(!driveConnected){showToast('Conecte seu Google Drive antes de cadastrar dados reais.','error');setPage('settings');return}if(kind==='company')renderCompanyForm(record);if(kind==='employee')renderEmployeeForm(record);if(kind==='contract')renderContractForm(record);if(kind==='document')renderDocumentForm()}

function validateData(raw){const out={schemaVersion:1,updatedAt:raw?.updatedAt||new Date().toISOString(),companies:Array.isArray(raw?.companies)?raw.companies:[],employees:Array.isArray(raw?.employees)?raw.employees:[],contracts:Array.isArray(raw?.contracts)?raw.contracts:[],documents:Array.isArray(raw?.documents)?raw.documents:[]};return out}
async function driveRequest(url,options={}){if(!accessToken)throw new Error('A sessão do Google Drive expirou. Conecte novamente.');const headers={...(options.headers||{}),Authorization:`Bearer ${accessToken}`};const response=await fetch(url,{...options,headers});if(response.status===401){accessToken=null;tokenExpiresAt=0;driveConnected=false;updateDriveUi();throw new Error('A autorização do Google Drive expirou. Conecte a conta novamente.')}if(!response.ok){let message=`Falha no Google Drive (${response.status}).`;try{const payload=await response.json();message=payload?.error?.message||message}catch{}throw new Error(message)}return response}
async function createDriveFile(metadata,content,contentType){const boundary=`gt-boundary-${crypto.randomUUID?crypto.randomUUID():Date.now()}`;const parts=[`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n`,`--${boundary}\r\nContent-Type: ${contentType||'application/octet-stream'}\r\n\r\n`,content,`\r\n--${boundary}--`];const body=new Blob(parts,{type:`multipart/related; boundary=${boundary}`});const url='https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields='+encodeURIComponent('id,name,mimeType,parents,webViewLink,modifiedTime');const res=await driveRequest(url,{method:'POST',body});return res.json()}
async function listWorkspaceFiles(){const q=`name = '${DB_NAME}' and trashed = false`;const url='https://www.googleapis.com/drive/v3/files?q='+encodeURIComponent(q)+'&pageSize=10&orderBy=modifiedTime%20desc&fields='+encodeURIComponent('files(id,name,mimeType,parents,modifiedTime,webViewLink)');const res=await driveRequest(url);const payload=await res.json();return payload.files||[]}
async function bootstrapDrive(){const found=await listWorkspaceFiles();if(found.length){const file=found[0];databaseId=file.id;driveFolderId=file.parents?.[0]||null;const res=await driveRequest(`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(databaseId)}?alt=media`);const raw=await res.text();data=validateData(raw.trim()?JSON.parse(raw):{});return}
  const folder=await driveRequest('https://www.googleapis.com/drive/v3/files?fields='+encodeURIComponent('id,name,mimeType'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'BancoDoc',mimeType:'application/vnd.google-apps.folder'})}).then(r=>r.json());driveFolderId=folder.id;
  data={schemaVersion:1,updatedAt:new Date().toISOString(),companies:[],employees:[],contracts:[],documents:[]};const jsonBlob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const record=await createDriveFile({name:DB_NAME,mimeType:'application/json',parents:[driveFolderId]},jsonBlob,'application/json');databaseId=record.id;
}
async function persistDatabase(){if(!driveConnected||!databaseId)throw new Error('Conecte o Drive antes de salvar.');const snapshot=JSON.stringify({...data,updatedAt:new Date().toISOString()},null,2);const task=writeQueue.catch(()=>{}).then(async()=>{const res=await driveRequest(`https://www.googleapis.com/upload/drive/v3/files/${encodeURIComponent(databaseId)}?uploadType=media`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:snapshot});await res.text();data.updatedAt=new Date().toISOString();syncState='clean';document.getElementById('sync-warning')?.classList.remove('visible');return true});writeQueue=task;try{return await task}catch(error){syncState='error';document.getElementById('sync-warning')?.classList.add('visible');throw error}}
function safeFilePart(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,45)||'arquivo'}
function bytesLabel(value){if(value<1024)return `${value} B`;if(value<1048576)return `${(value/1024).toFixed(0)} KB`;return `${(value/1048576).toFixed(1)} MB`}
function buildFileName(file,company,employee,type){const original=file.name||'arquivo';const dot=original.lastIndexOf('.');const ext=dot>0?original.slice(dot).replace(/[^.a-zA-Z0-9]/g,''):'';const stem=dot>0?original.slice(0,dot):original;return `${new Date().toISOString().slice(0,10)}__${safeFilePart(company)}__${safeFilePart(employee||'Empresa')}__${safeFilePart(type)}__${safeFilePart(stem)}${ext}`.slice(0,180)}
async function uploadDocumentFile(file,metadata){if(!driveFolderId)throw new Error('A pasta de destino do Drive não foi localizada. Reconecte a conta.');const name=buildFileName(file,metadata.company,metadata.employee,metadata.type);return createDriveFile({name,mimeType:file.type||'application/octet-stream',parents:[driveFolderId],description:`Documento enviado pelo portal de BancoDoc · ${metadata.type}`},file,file.type||'application/octet-stream')}
function extractCnpj(value){const digits=String(value||'').replace(/\D/g,'');return digits.length===14?digits.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4-$5'):''}
function extractDriveFolderId(value){const raw=String(value||'').trim();if(/^[A-Za-z0-9_-]{10,}$/.test(raw))return raw;return raw.match(/\/folders\/([A-Za-z0-9_-]+)/)?.[1]||raw.match(/[?&]id=([A-Za-z0-9_-]+)/)?.[1]||''}
async function getDriveFolder(folderId){const fields='id,name,mimeType,webViewLink,modifiedTime';const url=`https://www.googleapis.com/drive/v3/files/${encodeURIComponent(folderId)}?supportsAllDrives=true&fields=${encodeURIComponent(fields)}`;const res=await driveRequest(url);return res.json()}
async function listFolderChildren(folderId){const all=[];let pageToken='';do{const params=new URLSearchParams({q:`'${folderId}' in parents and trashed = false`,pageSize:'1000',orderBy:'modifiedTime desc',supportsAllDrives:'true',includeItemsFromAllDrives:'true',fields:'nextPageToken,files(id,name,mimeType,webViewLink,createdTime,modifiedTime,size,shortcutDetails)'});if(pageToken)params.set('pageToken',pageToken);const res=await driveRequest(`https://www.googleapis.com/drive/v3/files?${params.toString()}`);const payload=await res.json();all.push(...(payload.files||[]));pageToken=payload.nextPageToken||''}while(pageToken&&all.length<2000);return all}
async function listCompanyFiles(folderId,depth=0,visited=new Set()){if(depth>5||visited.has(folderId))return[];visited.add(folderId);const children=await listFolderChildren(folderId);const files=[];for(const item of children){if(item.mimeType==='application/vnd.google-apps.folder'){files.push(...await listCompanyFiles(item.id,depth+1,visited))}else if(item.mimeType!=='application/vnd.google-apps.shortcut'){files.push(item)}}return files}
function inferDocumentType(name){const n=norm(name);const rules=[[/ficha.{0,12}epi|epi.{0,12}ficha|entrega.{0,12}epi/,'Ficha de EPI'],[/(comprovante|recibo).{0,20}(guia|inss|fgts|darf|gps|dctfweb|grf)|pagamento.{0,20}(guia|inss|fgts|darf|gps|dctfweb|grf)/,'Comprovante de pagamento de guia'],[/guia.{0,15}inss|inss.{0,15}guia|\bgps\b/,'Guia de INSS'],[/guia.{0,15}fgts|fgts.{0,15}guia|\bgrf\b|\bgfd\b/,'Guia de FGTS'],[/dctfweb.{0,15}(darf|guia)|guia.{0,15}darf|\bdarf\b/,'Guia de DCTFWeb/DARF'],[/\bguia\b/,'Guia de recolhimento'],[/\bpgr\b/,'PGR'],[/\bpcmso\b/,'PCMSO'],[/\bltcat\b/,'LTCAT'],[/\baso\b/,'ASO'],[/\bppp\b/,'PPP'],[/\bcndt\b/,'CNDT'],[/certid[aã]o|certidao|regularidade.{0,12}fgts|fgts.{0,12}regularidade/,'Certidão'],[/\bfgts\b/,'Documento de FGTS'],[/\bfolha\b|holerite|contracheque/,'Folha de pagamento'],[/contrato/,'Contrato'],[/aditivo/,'Aditivo contratual'],[/insalubridade/,'Laudo de insalubridade'],[/periculosidade/,'Laudo de periculosidade'],[/treinamento|\bnr\s?\d+/,'Treinamento/NR']];return rules.find(([pattern])=>pattern.test(n))?.[1]||'Documento recebido'}
async function addCompanyFolder(value){if(!driveConnected){showToast('Conecte o Drive antes de vincular pastas.','error');return}const folderId=extractDriveFolderId(value);if(!folderId){showToast('Cole um link válido de pasta do Google Drive.','error');return}if(data.companies.some(c=>c.driveFolderId===folderId)){showToast('Esta pasta já está vinculada.');return}const form=document.getElementById('folder-link-form');const button=form?.querySelector('[type="submit"]');if(button){button.disabled=true;button.textContent='Verificando pasta…'}try{const folder=await getDriveFolder(folderId);if(folder.mimeType!=='application/vnd.google-apps.folder')throw new Error('O link informado não é uma pasta do Drive.');const company={id:id(),name:folder.name||'Empresa sem nome',cnpj:extractCnpj(folder.name),contact:'',email:'',phone:'',city:'',status:'Ativa',driveFolderId:folder.id,driveUrl:folder.webViewLink||`https://drive.google.com/drive/folders/${encodeURIComponent(folder.id)}`};data.companies.unshift(company);await persistDatabase();renderPage();showToast(`Empresa “${company.name}” criada pela pasta. Sincronizando arquivos…`,'success');await syncCompanyFolders();renderPage()}catch(error){if(button){button.disabled=false;button.innerHTML=`${icon('link')} Vincular e importar`}showToast(error.message||'Não foi possível ler a pasta. Confira se ela foi compartilhada com esta conta Google.','error')}}
async function unlinkCompanyFolder(companyId){if(!driveConnected)return;const company=data.companies.find(c=>c.id===companyId);if(!company)return;company.driveFolderId='';company.driveUrl='';try{await persistDatabase();renderPage();showToast(`A pasta de “${company.name}” foi desvinculada. Os documentos já importados foram mantidos.`,'success')}catch(error){showToast(error.message||'Não foi possível salvar a alteração.','error')}}
let companyFolderSyncRunning=false;
async function syncCompanyFolders(options={}){if(companyFolderSyncRunning)return;if(!driveConnected){if(!options.silent){showToast('Conecte o Drive antes de sincronizar pastas.','error');setPage('settings')}return}const companies=data.companies.filter(c=>c.driveFolderId);if(!companies.length){if(!options.silent)showToast('Vincule pelo menos uma pasta de empresa em Configurações.');return}if(tokenExpiresAt&&tokenExpiresAt<Date.now()+15000){if(!options.silent)showToast('A autorização do Drive expirou. Reconecte para sincronizar.','error');return}companyFolderSyncRunning=true;let imported=0,changed=false,failures=0;try{for(const company of companies){try{const files=await listCompanyFiles(company.driveFolderId);for(const file of files){let doc=data.documents.find(d=>d.driveFileId===file.id);const url=file.webViewLink||`https://drive.google.com/file/d/${encodeURIComponent(file.id)}/view`;if(!doc){doc={id:id(),type:inferDocumentType(file.name),companyId:company.id,employeeId:'',competency:'',issueDate:'',expiryDate:'',status:'Para análise',fileName:file.name,driveFileId:file.id,driveUrl:url,mimeType:file.mimeType||'',size:Number(file.size||0),modifiedTime:file.modifiedTime||'',createdTime:file.createdTime||'',notes:'Importado do Drive; confira os dados do documento.'};data.documents.unshift(doc);imported++;changed=true}else{const next={fileName:file.name||doc.fileName,driveUrl:url,mimeType:file.mimeType||doc.mimeType||'',size:Number(file.size||doc.size||0),modifiedTime:file.modifiedTime||doc.modifiedTime||'',createdTime:file.createdTime||doc.createdTime||''};if(Object.keys(next).some(k=>doc[k]!==next[k])){Object.assign(doc,next);changed=true}}}}catch(error){failures++;if(!options.silent)showToast(`Não consegui ler “${company.name}”: ${error.message}`,'error')}}if(changed)await persistDatabase();if(!options.silent){renderPage();showToast(`${imported} arquivo${imported===1?'':'s'} novo${imported===1?'':'s'} importado${imported===1?'':'s'}${failures?`; ${failures} pasta(s) com erro`:''}.`,'success')}}catch(error){if(!options.silent)showToast(error.message||'Falha ao sincronizar as pastas.','error')}finally{companyFolderSyncRunning=false}}
function markChangedAndRender(){syncState='dirty';renderPage()}
async function saveRecord(form){if(!driveConnected){showToast('Conecte o Google Drive para gravar os dados.','error');return}const kind=form.dataset.kind,formData=new FormData(form),recordId=formData.get('id'),button=form.querySelector('[type="submit"]');if(button){button.disabled=true;button.textContent=kind==='document'?'Enviando…':'Salvando…'}
 try{
  if(kind==='company'){const values={id:recordId||id(),name:String(formData.get('name')||'').trim(),cnpj:String(formData.get('cnpj')||'').trim(),contact:String(formData.get('contact')||'').trim(),city:String(formData.get('city')||'').trim(),email:String(formData.get('email')||'').trim(),phone:String(formData.get('phone')||'').trim(),status:String(formData.get('status')||'Ativa')};const index=data.companies.findIndex(x=>x.id===values.id);if(index>=0)data.companies[index]=values;else data.companies.unshift(values);await persistDatabase();closeModal();renderPage();showToast('Empresa salva no Drive.','success');return}
  if(kind==='employee'){const values={id:recordId||id(),name:String(formData.get('name')||'').trim(),cpf:String(formData.get('cpf')||'').trim(),position:String(formData.get('position')||'').trim(),companyId:String(formData.get('companyId')||''),admissionDate:String(formData.get('admissionDate')||''),phone:String(formData.get('phone')||'').trim(),status:String(formData.get('status')||'Ativo')};const index=data.employees.findIndex(x=>x.id===values.id);if(index>=0)data.employees[index]=values;else data.employees.unshift(values);await persistDatabase();closeModal();renderPage();showToast('Colaborador salvo no Drive.','success');return}
  if(kind==='contract'){const values={id:recordId||id(),number:String(formData.get('number')||'').trim(),companyId:String(formData.get('companyId')||''),startDate:String(formData.get('startDate')||''),endDate:String(formData.get('endDate')||''),monthlyValue:String(formData.get('monthlyValue')||''),status:String(formData.get('status')||'Ativo'),notes:String(formData.get('notes')||'').trim()};const index=data.contracts.findIndex(x=>x.id===values.id);if(index>=0)data.contracts[index]=values;else data.contracts.unshift(values);await persistDatabase();closeModal();renderPage();showToast('Contrato salvo no Drive.','success');return}
  if(kind==='document'){const file=formData.get('file');if(!(file instanceof File)||!file.size)throw new Error('Selecione um arquivo para enviar.');if(file.size>50*1024*1024)throw new Error(`O arquivo tem ${bytesLabel(file.size)}. Envie arquivos de até 50 MB nesta versão.`);const companyId=String(formData.get('companyId')||'');const employeeId=String(formData.get('employeeId')||'');const type=String(formData.get('type')||'');if(!companyId||!type)throw new Error('Informe empresa e tipo de documento.');const uploaded=await uploadDocumentFile(file,{company:companyName(companyId),employee:employeeName(employeeId),type});const item={id:id(),type,companyId,employeeId,competency:String(formData.get('competency')||'').trim(),issueDate:String(formData.get('issueDate')||''),expiryDate:String(formData.get('expiryDate')||''),status:String(formData.get('status')||'Para análise'),fileName:uploaded.name||file.name,driveFileId:uploaded.id,driveUrl:uploaded.webViewLink||`https://drive.google.com/file/d/${encodeURIComponent(uploaded.id)}/view`,mimeType:file.type||'application/octet-stream',size:file.size,notes:String(formData.get('notes')||'').trim()};data.documents.unshift(item);try{await persistDatabase()}catch(error){closeModal();renderPage();showToast('O arquivo foi enviado ao Drive, mas o cadastro não sincronizou. Use “Tentar novamente” para salvar a lista.','error');return}closeModal();renderPage();showToast('Documento enviado e registrado no Google Drive.','success');return}
 }catch(error){showToast(error.message||'Não foi possível salvar.','error');if(button){button.disabled=false;button.innerHTML=kind==='document'?`${icon('upload')} Enviar para o Drive`:'Salvar'} }
}
async function updateDocumentStatus(docId,status){if(!driveConnected){showToast('Conecte o Drive para alterar a situação.','error');renderPage();return}const doc=data.documents.find(d=>d.id===docId);if(!doc)return;doc.status=status;try{await persistDatabase();renderPage();showToast('Situação atualizada.','success')}catch(error){renderPage();showToast(error.message,'error')}}

function saveClientId(){const input=document.getElementById('google-client-id');const value=input?.value.trim()||'';if(!value){showToast('Informe o Client ID do aplicativo Web do Google.','error');input?.focus();return false}if(!value.endsWith('.apps.googleusercontent.com')){showToast('Confira o formato do Client ID. Ele deve terminar em .apps.googleusercontent.com.','error');input?.focus();return false}localStorage.setItem(CLIENT_KEY,value);showToast('Client ID salvo neste navegador.','success');return true}
function startOAuth(){const input=document.getElementById('google-client-id');const clientId=input?.value.trim()||localStorage.getItem(CLIENT_KEY)||'';if(!clientId){setPage('settings');showToast('Informe primeiro o Client ID do Google Cloud.','error');return}if(input&&clientId)localStorage.setItem(CLIENT_KEY,clientId);if(!window.google?.accounts?.oauth2){showToast('A biblioteca de autorização do Google ainda está carregando. Aguarde alguns segundos e tente novamente.','error');return}syncState='connecting';updateDriveUi();const client=window.google.accounts.oauth2.initTokenClient({client_id:clientId,scope:DRIVE_SCOPE,include_granted_scopes:true,callback:async response=>{if(response.error||!response.access_token){syncState='clean';updateDriveUi();showToast(response.error_description||response.error||'A autorização não foi concluída.','error');return}accessToken=response.access_token;tokenExpiresAt=Date.now()+(Number(response.expires_in||3600)*1000);try{await bootstrapDrive();driveConnected=true;syncState='clean';updateDriveUi();renderPage();if(data.companies.some(c=>c.driveFolderId))await syncCompanyFolders();renderPage();showToast('Google Drive conectado. O BancoDoc está pronto para sincronizar suas pastas.','success')}catch(error){accessToken=null;driveConnected=false;syncState='clean';data=structuredClone(demoData);databaseId=null;driveFolderId=null;updateDriveUi();renderPage();showToast(error.message||'Não foi possível carregar a pasta do Drive.','error')}}});client.requestAccessToken({prompt:''})}
function disconnectDrive(){accessToken=null;tokenExpiresAt=0;driveConnected=false;databaseId=null;driveFolderId=null;syncState='clean';data=structuredClone(demoData);updateDriveUi();renderPage();showToast('Conta desconectada deste navegador. Os arquivos continuam no Google Drive.')}
async function retrySync(){if(!driveConnected){showToast('Reconecte o Google Drive para sincronizar.','error');setPage('settings');return}try{await persistDatabase();showToast('Dados sincronizados com o Drive.','success');renderPage()}catch(error){showToast(error.message,'error')}}
function exportCsv(){if(!data.documents.length){showToast('Não há documentos para exportar.');return}const rows=[['Empresa','CNPJ','Colaborador','Documento','Competência','Emissão','Validade','Situação','Arquivo no Drive']];for(const d of data.documents){rows.push([companyName(d.companyId),companyById(d.companyId)?.cnpj||'',employeeName(d.employeeId),d.type,d.competency||'',d.issueDate||'',d.expiryDate||'',docStatus(d),d.driveUrl||''])}const csv='\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`relatorio-documentos-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
function renderCompanies(){const items=data.companies.filter(c=>searchMatch(c.name,c.cnpj,c.contact,c.city));const rows=items.map((c,i)=>{const staff=data.employees.filter(e=>e.companyId===c.id).length;const docs=data.documents.filter(d=>d.companyId===c.id);const issues=docs.filter(d=>!['Aprovado','Vence em breve'].includes(d.status)||docStatus(d)==='Vencido').length;return `<tr><td>${companyCell(c,i)}</td><td>${docs.length?pill(issues?`${issues} pendência${issues>1?'s':''}`:'Para análise'):'<span class="muted">Aguardando arquivos</span>'}</td><td>${c.driveUrl?`<a class="subtle-action" href="${esc(c.driveUrl)}" target="_blank" rel="noopener">Abrir pasta</a>`:'<span class="muted">Sem pasta vinculada</span>'}</td></tr>`}).join('');return `${titleBlock('Empresas','Cada pasta vinculada cria uma empresa automaticamente. Os arquivos são importados do Google Drive.','<button class="button button-primary" data-page-link="settings">'+icon('link')+' Vincular pasta</button>')}${syncWarning()}<div class="section-toolbar"><div class="toolbar-left"><span class="muted" style="font-size:9px">${items.length} empresa${items.length===1?'':'s'} encontrada${items.length===1?'':'s'}</span></div><div class="toolbar-right"><button class="button button-small" data-action="sync-folders">${icon('refresh')} Sincronizar pastas</button></div></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table record-table"><thead><tr><th>Empresa (nome da pasta)</th><th>Documentos importados</th><th>Pasta de envio</th></tr></thead><tbody>${rows||`<tr><td colspan="3">${emptyState(searchTerm?'Nenhuma empresa encontrada':'Nenhuma pasta vinculada','Conecte o Drive e informe o link da pasta de cada empresa nas Configurações.','folder')}</td></tr>`}</tbody></table></div><div class="table-footer">Compartilhe com cada empresa somente a pasta dela e permita adicionar arquivos. O portal ainda não possui login; restrinja o acesso antes de armazenar documentos confidenciais.</div></section>`}
function renderDocuments(){const items=data.documents.filter(d=>searchMatch(d.type,d.competency,d.fileName,companyName(d.companyId),employeeName(d.employeeId)));const rows=items.map(d=>`<tr><td><div class="doc-name"><span class="file-type-icon">${icon('file')}</span><span><span class="primary-cell">${esc(d.type)}</span><span class="secondary-cell">${esc(d.fileName||'')}</span></span></div></td><td>${companyCell(companyById(d.companyId),1)}</td><td>${fmtDate((d.modifiedTime?d.modifiedTime.slice(0,10):d.uploadedAt||d.issueDate))}</td><td><select class="status-select ${statusClass(d.status||'Para análise')}" data-doc-status="${esc(d.id)}" aria-label="Alterar situação do documento"><option ${d.status==='Para análise'?'selected':''}>Para análise</option><option ${d.status==='Aprovado'?'selected':''}>Aprovado</option><option ${d.status==='Reprovado'?'selected':''}>Reprovado</option></select></td><td class="actions-cell">${d.driveUrl?`<a class="subtle-action doc-link" href="${esc(d.driveUrl)}" target="_blank" rel="noopener">Abrir arquivo</a>`:'<span class="muted">—</span>'}</td></tr>`).join('');return `${titleBlock('Documentos','Arquivos encontrados nas pastas vinculadas. O nome e a data vêm do Drive; cada documento entra para análise.','<button class="button button-primary" data-action="sync-folders">'+icon('refresh')+' Sincronizar agora</button>')}${syncWarning()}<div class="section-toolbar"><div class="toolbar-left"><span class="muted" style="font-size:9px">${items.length} documento${items.length===1?'':'s'}</span></div></div><section class="panel table-panel"><div class="table-wrap"><table class="data-table record-table"><thead><tr><th>Documento identificado</th><th>Empresa</th><th>Última alteração no Drive</th><th>Situação</th><th></th></tr></thead><tbody id="document-rows">${rows||`<tr><td colspan="5">${emptyState('Nenhum arquivo importado','Vincule as pastas das empresas e sincronize o Drive.','file')}</td></tr>`}</tbody></table></div><div class="table-footer">O BancoDoc importa metadados e o link do arquivo. A leitura do conteúdo do PDF e o preenchimento automático de validade ainda precisam de OCR/backend.</div></section>`}
function renderSettings(){const clientId=localStorage.getItem(CLIENT_KEY)||'';const folderLink=driveFolderId?`https://drive.google.com/drive/folders/${encodeURIComponent(driveFolderId)}`:'';const folders=data.companies.filter(c=>c.driveFolderId);const folderRows=folders.map(c=>`<div class="folder-line-row"><span class="folder-line-copy">${icon('folder')}<span><strong>${esc(c.name)}</strong><small>${esc(c.driveFolderId)}</small></span></span><span class="folder-line-actions">${c.driveUrl?`<a class="subtle-action" href="${esc(c.driveUrl)}" target="_blank" rel="noopener">Abrir</a>`:''}<button class="subtle-action" data-unlink-folder="${esc(c.id)}">Desvincular</button></span></div>`).join('');return `${titleBlock('Configurações','Conecte o seu Google Drive e vincule as pastas de envio das empresas.','')}${syncWarning()}<div class="settings-grid"><section class="panel settings-panel"><h2>Conexão do administrador</h2><p class="settings-intro">O BancoDoc usa sua conta Google para guardar a base do portal e consultar os nomes, datas e links dos arquivos nas pastas que você vincular.</p><div class="settings-status"><span class="settings-status-icon">${icon(driveConnected?'check':'cloud')}</span><div class="settings-status-copy"><strong>${driveConnected?'Drive conectado':'Drive ainda não conectado'}</strong><span>${driveConnected?'Conexão ativa nesta sessão do navegador.':'Configure o Client ID e autorize o acesso do administrador.'}</span></div>${driveConnected?`<button class="button button-small" data-action="disconnect-drive">Desconectar</button>`:''}</div>${driveConnected?`<div class="field"><label>Dados do BancoDoc</label><a class="folder-line" href="${esc(folderLink)}" target="_blank" rel="noopener">${icon('folder')} Abrir pasta “BancoDoc” no Drive ${icon('arrow-up-right')}</a><small>A base do portal fica separada das pastas de envio das empresas.</small></div>`:''}<div class="field"><label for="google-client-id">ID do cliente OAuth do Google</label><input id="google-client-id" type="text" inputmode="url" autocomplete="off" spellcheck="false" placeholder="000000000000-abc123.apps.googleusercontent.com" value="${esc(clientId)}"><small>É o Client ID do tipo “Aplicativo da Web”. Não coloque o Client Secret. O Client ID fica salvo somente neste navegador.</small></div><div class="form-actions"><button class="button" data-action="save-client-id">Salvar configuração</button><button class="button button-primary" data-action="connect-drive">${icon('cloud')} ${driveConnected?'Reconectar ao Google Drive':'Conectar Google Drive'}</button></div></section><section class="panel settings-panel"><h2>Pastas das empresas</h2><p class="settings-intro">Cole o link de uma pasta compartilhada. O nome dela será usado para criar a empresa, sem cadastro manual.</p>${driveConnected?`<form id="folder-link-form" class="folder-link-form"><div class="field"><label for="company-folder-url">Link da pasta no Google Drive</label><input id="company-folder-url" name="folderUrl" type="url" placeholder="https://drive.google.com/drive/folders/..." required></div><div class="form-actions"><button class="button button-primary" type="submit">${icon('link')} Vincular e importar</button><button class="button" type="button" data-action="sync-folders">${icon('refresh')} Sincronizar todas</button></div></form><div class="folder-list">${folderRows||emptyState('Nenhuma pasta vinculada','Conecte uma pasta por empresa. O nome da pasta cria o registro automaticamente.','folder')}</div>`:`<div class="empty-state">${icon('cloud')}<strong>Conecte o Drive para vincular pastas</strong><span>Após autorizar, cole um link por empresa.</span></div>`}<p class="form-footnote">No Drive, compartilhe cada pasta somente com a empresa correspondente, com permissão para adicionar arquivos. Não compartilhe a pasta de dados do BancoDoc.</p></section><aside class="info-card"><h3>Como funciona</h3><ul><li>Você compartilha um link de pasta separado com cada empresa.</li><li>Você cola o link aqui; o nome da pasta cria o cadastro da empresa.</li><li>O painel importa nomes, datas, links e pastas internas encontrados no Drive.</li><li>Arquivos novos são sincronizados enquanto o painel está aberto e ao clicar em “Sincronizar”.</li></ul><p><strong>Permissão Google:</strong> o consentimento autoriza a consulta de metadados do Drive da conta (nomes, pastas e datas). O BancoDoc lista apenas as pastas vinculadas e não baixa o conteúdo dos documentos nesta versão.</p><p>Configure a Drive API, a tela de consentimento OAuth e um Client ID de aplicativo Web. Origem autorizada: <span class="connection-code">https://gestao-de-terceiros.elizangelay2.chatgpt.site</span></p><p class="privacy-note">As empresas enviam arquivos para suas próprias pastas e não precisam acessar o portal. O site está público e ainda não possui login administrativo; restrinja o acesso antes de usar documentos confidenciais.</p></aside></div>`}
function routeAction(action){if(action==='add-company')setPage('settings');else if(action==='add-employee')openForm('employee');else if(action==='add-contract')openForm('contract');else if(action==='add-document')openForm('document');else if(action==='open-settings')setPage('settings');else if(action==='close-modal')closeModal();else if(action==='save-client-id')saveClientId();else if(action==='connect-drive')startOAuth();else if(action==='disconnect-drive')disconnectDrive();else if(action==='sync')retrySync();else if(action==='sync-folders')syncCompanyFolders();else if(action==='export-csv')exportCsv()}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-page]');if(nav){setPage(nav.dataset.page);return}const pageLink=event.target.closest('[data-page-link]');if(pageLink){setPage(pageLink.dataset.pageLink);return}const action=event.target.closest('[data-action]');if(action){routeAction(action.dataset.action);return}const edit=event.target.closest('[data-edit]');if(edit){const kind=edit.dataset.edit;const collection={company:data.companies,employee:data.employees,contract:data.contracts}[kind];openForm(kind,collection?.find(x=>x.id===edit.dataset.id));return}});
document.addEventListener('submit',event=>{if(event.target.id==='record-form'){event.preventDefault();saveRecord(event.target)}if(event.target.id==='folder-link-form'){event.preventDefault();addCompanyFolder(new FormData(event.target).get('folderUrl'))}});
document.addEventListener('click',event=>{const button=event.target.closest('[data-unlink-folder]');if(button)unlinkCompanyFolder(button.dataset.unlinkFolder)});
window.addEventListener('focus',()=>{if(driveConnected&&document.visibilityState==='visible')syncCompanyFolders({silent:true})});
document.addEventListener('visibilitychange',()=>{if(driveConnected&&document.visibilityState==='visible')syncCompanyFolders({silent:true})});
setInterval(()=>{if(driveConnected&&document.visibilityState==='visible')syncCompanyFolders({silent:true})},120000);
document.addEventListener('change',event=>{if(event.target.matches('[data-doc-status]'))updateDocumentStatus(event.target.dataset.docStatus,event.target.value)});
document.getElementById('global-search').addEventListener('input',event=>{searchTerm=event.target.value;renderPage()});
document.getElementById('mobile-menu').addEventListener('click',()=>document.body.classList.toggle('mobile-open'));
document.getElementById('mobile-backdrop').addEventListener('click',()=>document.body.classList.remove('mobile-open'));
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.getElementById('global-search').focus()}if(event.key==='Escape'){closeModal();document.body.classList.remove('mobile-open')}});
if(clientIdStored){localStorage.setItem(CLIENT_KEY,clientIdStored)}
updateDriveUi();renderPage();
